                for (var p = 0; p < kept.Count; p++)
                {
                    var c = kept[p];
                    var hue = (c.ClassId * 37) % 360;
                    var stroke = ColorFromHsv(hue, 0.65f, 0.95f);
                    using (var pen = new Pen(Color.FromArgb(220, stroke), 8f))
                    {
                        var ox1 = (c.X1Lb - lb.PadLeft) / lb.Gain;
